// This file is generated by AI.

// 文档链接目标解析的测试: URI -> 项目内路径与文件类别。

import { describe, expect, it } from 'vitest';

import { linkTargetOf } from './document-link';

describe('linkTargetOf', () => {
  it('识别场景脚本', () => {
    expect(linkTargetOf('file:///C:/Game%20Project/game/scene/start.txt')).toEqual({
      path: 'C:\\Game Project\\game\\scene\\start.txt',
      kind: 'scene',
    });
  });

  it('按扩展名识别媒体资源', () => {
    expect(linkTargetOf('file:///C:/project/game/background/bg.png')).toEqual({
      path: 'C:\\project\\game\\background\\bg.png',
      kind: 'image',
    });
    expect(linkTargetOf('file:///C:/project/game/bgm/theme.mp3')?.kind).toBe('audio');
    expect(linkTargetOf('file:///C:/project/game/vocal/voice.wav')?.kind).toBe('audio');
    expect(linkTargetOf('file:///C:/project/game/video/op.mp4')?.kind).toBe('video');
    // 动画是 JSON, 按文本打开
    expect(linkTargetOf('file:///C:/project/game/animation/fadeIn.json')?.kind).toBe('text');
  });

  it('解码百分号编码与 Monaco 序列化的盘符', () => {
    // Monaco 会把 `file:///C:/...` 序列化为 `file:///c%3A/...`
    expect(linkTargetOf('file:///c%3A/project/game/figure/%E7%AB%8B%E7%BB%98.png')).toEqual({
      path: 'C:\\project\\game\\figure\\立绘.png',
      kind: 'image',
    });
  });

  it('忽略非文件协议与空路径', () => {
    expect(linkTargetOf('https://example.com/bg.png')).toBeNull();
    expect(linkTargetOf('')).toBeNull();
  });
});
